import Component from 'flarum/common/Component';
import { t } from '../util';
const TOPICS = ['companions', 'dashboard', 'audit', 'score', 'links', 'search', 'google_key', 'opportunities', 'speed', 'regressions', 'internal', 'ai', 'indexnow', 'rules', 'diagnostics', 'settings', 'privacy'];
const STEPS = {
  google_key: 7
};

/** Plain-words help for each section. */
export default class Guide extends Component {
  view() {
    return m("div", {
      className: "SurveyorSection SurveyorGuide"
    }, TOPICS.map(topic => m("section", {
      id: `surveyor-guide-${topic}`
    }, m("h3", null, t(`guide.${topic}_title`)), STEPS[topic] ? m("ol", null, Array.from({
      length: STEPS[topic]
    }, (_, i) => m("li", null, t(`guide.${topic}_step_${i + 1}`)))) : m("p", null, t(`guide.${topic}_body`)))));
  }
}
flarum.reg.add('ernestdefoe-surveyor', 'admin/workspace/Guide', Guide);